"use client"

import * as React from "react"
import { RotateCw, Sparkles } from "lucide-react"

import { Button } from "@/components/ui/button"
import { TextEffect } from "@/components/ui/text-effect"

const customVariants = {
  container: {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.04,
        delayChildren: 0.1,
      },
    },
    exit: {
      opacity: 0,
      transition: { staggerChildren: 0.02, staggerDirection: -1 },
    },
  },
  item: {
    hidden: {
      opacity: 0,
      y: 20,
      rotateX: -45,
      filter: "blur(6px)",
    },
    visible: {
      opacity: 1,
      y: 0,
      rotateX: 0,
      filter: "blur(0px)",
      transition: {
        type: "spring" as const,
        stiffness: 300,
        damping: 20,
      },
    },
    exit: {
      opacity: 0,
      y: -10,
      filter: "blur(4px)",
    },
  },
}

export default function TextEffectCustomVariants() {
  const [trigger, setTrigger] = React.useState(true)

  const replay = () => {
    setTrigger(false)
    window.setTimeout(() => setTrigger(true), 80)
  }

  return (
    <div className="flex w-full max-w-lg flex-col items-center gap-6 rounded-xl border border-border bg-card p-8 text-center shadow-xs">
