          {muted ? <MicOffIcon className="size-4" /> : <MicIcon className="size-4" />}
          <span>{muted ? "已静音" : "麦克风开启"}</span>
        </Toggle>
      </div>

      <div className="flex items-center gap-2">
        <Toggle
          variant="default"
          pressed={pinned}
          onPressedChange={setPinned}
          aria-label={pinned ? "取消窗口置顶" : "置顶窗口"}
